  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Francis Halzen",
        "Albrecht Karle",
        "Christian Spiering"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube established high-energy neutrinos as a new observational channel for the Universe, a major advance in astroparticle physics with lasting scientific reach.",
        "attribution": "Halzen's leadership and the detector's realization and scientific development merit recognition; Karle and Spiering represent central experimental contributions. Credit across the large collaboration remains difficult to delimit.",
        "maturity": "The detection is robust and has supported a sustained research program, though identifying the full range of sources is ongoing.",
        "uncertainties": [
          "How much of the discovery credit can fairly be assigned to three individuals rather than the collaboration."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Peter Jenni",
        "Tejinder Virdee",
        "Fabiola Gianotti"
      ],
      "assessment": {
        "nobel_worthiness": "The experimental discovery of the Higgs boson confirmed a central element of the Standard Model and stands among the most consequential particle physics results.",
        "attribution": "Jenni and Gianotti led ATLAS at key stages, while Virdee was a founding leader of CMS. The discovery depended on both experiments and thousands of contributors, making individual credit intrinsically constrained.",
        "maturity": "The signal was independently established by ATLAS and CMS and subsequent measurements have reinforced the discovery.",
        "uncertainties": [
          "Selecting individual representatives risks under-crediting the experimental teams and other leaders, including CMS leadership."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B037",
      "proposed_laureates": [
        "Sheperd S. Doeleman",
        "Heino Falcke",
        "Ramesh Narayan"
      ],
      "assessment": {
        "nobel_worthiness": "Event Horizon Telescope images made the immediate environment of black holes observable and gave striking tests of strong-gravity predictions.",
        "attribution": "Doeleman led the observational effort, Falcke helped develop the imaging concept and interpretation, and Narayan contributed theoretical modeling. The result was a large international collaboration.",
        "maturity": "Images of more than one black hole and continuing analysis give the achievement durable experimental grounding.",
        "uncertainties": [
          "The relative share of credit among the named scientists and the wider collaboration."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Peter W. Shor",
        "Andrew M. Steane"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected despite noise, establishing a foundation for fault-tolerant quantum computation.",
        "attribution": "Kitaev's topological codes and the independent foundational codes of Shor and Steane are complementary landmark contributions.",
        "maturity": "The principles are established and underpin active experimental progress, although large-scale fault-tolerant machines remain unrealized.",
        "uncertainties": [
          "Whether the award should recognize the theoretical foundations now or await large-scale demonstrations."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B047",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and enable stringent tests of fundamental physics as well as practical improvements in measurement.",
        "attribution": "Katori and Ye independently developed leading approaches and drove the field's experimental realization.",
        "maturity": "The technique has been repeatedly demonstrated and refined across laboratories, with clear scientific uses beyond clock development.",
        "uncertainties": [
          "How to distinguish the foundational advances from subsequent contributions across the international clock community."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Maura McLaughlin",
        "Michael Kramer",
        "Xavier Siemens"
      ],
      "assessment": {
        "nobel_worthiness": "Pulsar timing array evidence for a nanohertz gravitational-wave background opened a frequency range inaccessible to ground-based interferometers.",
        "attribution": "McLaughlin and Kramer represent key pulsar timing efforts, while Siemens contributed to the analysis and interpretation of the background. Multiple international arrays contributed to the emerging result.",
        "maturity": "The signal is supported by independent collaborations, but the evidence and its astrophysical interpretation are still developing.",
        "uncertainties": [
          "Whether the background's source population is sufficiently identified and the detection sufficiently settled for recognition."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Nergis Mavalvala"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light enables measurements beyond the ordinary quantum noise limit and has become an important tool in gravitational-wave interferometry.",
        "attribution": "Caves established key theoretical ideas, Kimble advanced experimental quantum optics, and Mavalvala helped bring squeezed-light methods into gravitational-wave detection.",
        "maturity": "The method has been demonstrated in operating detectors and contributes to a mature precision-measurement program.",
        "uncertainties": [
          "How much recognition should attach to the foundational technique versus its later detector implementation."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Paul B. Corkum",
        "Maciej Lewenstein"
      ],
      "assessment": {
        "nobel_worthiness": "Electron recollision and its quantum description underpin strong-field methods that created new ways to probe ultrafast atomic and molecular dynamics.",
        "attribution": "Corkum's physical picture and Lewenstein's theoretical formulation are closely linked contributions to the field's foundation.",
        "maturity": "The framework has guided decades of experiments and developed into a broad, established research area.",
        "uncertainties": [
          "The boundary between this contribution and later attosecond advances already recognized by the 2023 Physics Nobel."
        ]
      }
    }
  ]
}
